class _KeySegment:
    """
    Private Class: _KeySegment
    ==========================

    Simple dataclass that contains any hashable as a key and optionally a link
    to the parent, i.e. the KeyMap instance where this key is registered at.

    This is supposed to be a private class, so ideally the normal user will
    never actively get in contact with this.
    """

    # the class-level parent. Anonymous _KeySegment instances can have a class
    # assigned to them if they are generated on the fly.
    _cparent = None

    def __init__(self, key, parent=None):
        if __debug__:
            print(f"generate key from {type(key).__name__} '{key}'")

        # make sure key is hashable
        assert isinstance(key, Hashable)

        # check for potential input arg conversion
        if isinstance(key, _KeySegment):
            self._key = key.key
        elif isinstance(key, Key):
            assert len(key.keys) == 1, "cannot generate _Key from chained key"
            self._key = key.keys[0].key
        else:
            self._key = key

        # check explicit parent, use class parent otherwise
        if parent is not None:
            assert self._cparent is None, "Cannot overwrite parent tag"
            assert isinstance(parent, KeyMap), f"Invalid parent {type(parent)}"
            self._parent = parent
        else:
            self._parent = self._cparent

        # final check
        assert not isinstance(self._key, (_KeySegment, Key))

    def __init_subclass__(cls, parent=None):
        """set default parent upon inheritance"""
        cls._cparent = parent

    def __hash__(self):
        """pull the hash request into the key attribute"""
        return hash(self._key)

    def __eq__(self, other):
        assert isinstance(
            other, _KeySegment
        ), f"Invalid comparison between {type(self)} and {type(other)}"
        return self.key == other.key

    @property
    def key(self) -> Any:
        """access protected attribute key."""
        return self._key

    @property
    def parent(self):
        """access read-only parameter parent"""
        return self._parent

    def __str__(self):
        return f"[{self._key}]"

    def __repr__(self):
        return f"[{self._key}]"


class _ForbiddenKey(_KeySegment):
    """To simplify the implementation, of the Entry(KeyMap) class, we will
    introduce an _KeySegment child class, that simply throws an exception from
    the constructor.
    """

    def __new__(cls, *_args, **_kwargs):
        """Entry classes do not allow keygens as they are not supposed to
        generate keys. So let's brutally kill the mere attempt."""
        raise KeyError("No keys allowed to be created here")


