class KeyMap:
    """Keymap class description"""

    _IDENTIFIER = "KeyMap"
    _IDENTIFIER_SHORT = "KM"
    _enum = 0

    @autoname
    def __init__(self, name=None):
        super().__init__()

        self._name = name

        # start empty
        self._size = 0

        # contain nested keymaps, regions or entries
        self._content = []

        # remember what you are attached to
        self._parents = []

        # lookup tables
        self._pos2reg = []  # translate from pos to key reg
        self._pos2key = []  # translate from pos to key
        self._key2pos = {}  # translate the key to its position
        self._key2reg = {}  # key objects are keys to regs

        # reset
        self._reset()

        # this actually does not make a difference, but it feels more safe to
        # start with False
        self._is_ud_flag = False

        self._keygen = self._generate_keygen(name)

    def _reset(self):
        """reset anything that has to do with counters and offsets"""
        self._is_ud_flag = False
        self._size = 0
        self._pos2reg = []
        self._pos2key = []
        self._key2pos = {}
        self._key2reg = {}

    @property
    def name(self):
        """get name (protected access)"""
        return self._name

    @name.setter
    def name(self, name):
        print("Bad programmer, bad! But seriously, be careful with renaming.")
        self._name = name

    @property
    def size(self):
        """get size (protected access)"""
        return self._size

    def __str__(self):
        self.update()
        return f"<{self._IDENTIFIER} '{self.name}'>"

    def __repr__(self):
        self.update()
        return f"<{self._IDENTIFIER_SHORT}[{self.name}]>"

    def __len__(self):
        self.update()
        assert self._size == sum(
            len(keymap) for keymap in self.values(recursive=True)
        )
        return self._size

    def key(self, key):
        """generate a key object from with the KeyMaps own keygen"""
        return self._keygen(key)

    def _generate_keygen(self, name) -> Type:
        """the keygenerator class can be tagged by a parent"""
        this_class = type(
            f"auto_KeyGen_{name}",
            (_KeySegment,),
            {
                "__doc__": f"auto generated key generator for keymap '{name}'.",
            },
            parent=self,
        )
        return this_class

    @property
    def is_ud(self) -> bool:
        """read-only access to update flag"""
        return self._is_ud_flag

    def flag_ud(self):
        """mark for update"""
        self._is_ud_flag = False
        for parent in self._parents:
            parent.flag_ud()

    @staticmethod
    def from_file(filename) -> KeyMap:
        """get the keymap from a file"""
        with open(filename, "rb") as handle:
            ret = pickle.load(handle)
        ret.flag_ud()
        ret.__class__._enum += 1
        ret.update()
        return ret

    def to_file(self, filename) -> None:
        """write the keymap to a file"""
        self.update()
        with open(filename, "wb") as handle:
            pickle.dump(self, handle)

    def reorder(self, function) -> Self:
        """reorder the arrangement of keys in the map by some sorting function"""
        aux = sorted(
            [
                (sort_id, key, keymap)
                for key, keymap in self._content
                if (sort_id := function(key, keymap)) is not None
            ]
        )
        self._content = [(key, keymap) for _, key, keymap in aux]
        return self

    def append(self, key=None, keymap=None, no_override=True):
        """append a keymap object at a key"""

        if key is None:
            assert keymap is not None
            key = keymap.name

        # force-make it a key
        key_obj = self.key(key)

        if keymap is None:
            # default thing to add is an entry
            keymap = Entry(str(key_obj))

        # check if key is duplicate
        if no_override:
            for tkey, _ in self._content:
                if tkey == key_obj:
                    raise KeyError(f"Key '{key_obj}' already exists")

        # acutal append
        self._append(key_obj, keymap)

        # register the current keymap as a parent to the included keymap
        keymap.add_parent(self)
        self.flag_ud()

    def _append(self, key, keymap):
        """internal append, contains all checks and stuff"""
        assert isinstance(key, _KeySegment)
        self._content.append((key, keymap))

    def add_parent(self, parent):
        """add as a parent if not yet there"""
        if parent not in self._parents:
            self._parents.append(parent)

    def update(self):
        """user-friendly update procedure. Skips update if already up to date,
        asserts up-to-date flag and"""
        ret = True
        if not self.is_ud:
            ret = self._update()
        assert ret, "update did not succeed"
        return self

    def _update(self):
        """the actual update routine"""

        # reset internal stuff
        self._reset()
        offset_pointer = 0

        # go through keymaps in content
        for tkey, keymap in self._content:
            keymap.update()
            if keymap.size <= 0:
                print(f"skipping keymap {keymap} as it is empty")
                continue

            # move into the selected keymap
            self._key2reg[tkey] = keymap
            self._key2pos[tkey] = offset_pointer
            for offset in range(len(keymap)):
                self._pos2reg.append((keymap, offset))
                self._pos2key.append((tkey))
                offset_pointer += 1
        assert len(self._pos2reg) == offset_pointer
        self._size = offset_pointer
        self._is_ud_flag = True
        return self._is_ud_flag

    def __getitem__(self, key):
        self.update()
        if isinstance(key, Key):
            return self._key2reg[key._keys[0]]
        if not isinstance(key, _KeySegment):
            return self._key2reg[_KeySegment(key)]
        return self._key2reg[key]

    def keys(self, recursive=False, prefix=Key()):
        """generator equivalent to dict's keys function"""
        for key, reg in self._key2reg.items():
            if recursive:
                yield from reg.keys(recursive=True, prefix=Key(prefix, key))
            else:
                yield Key(prefix, key)

    def items(self, recursive=False, prefix=Key()):
        """generator equivalent to dict's items function"""
        for key, reg in self._key2reg.items():
            if recursive:
                yield from reg.items(recursive=True, prefix=Key(prefix, key))
            else:
                yield Key(key), reg

    def values(self, recursive=False):
        """generator equivalent to dict's values function"""
        for key, reg in self._key2reg.items():
            if recursive:
                yield from reg.values(recursive=True)
            else:
                yield reg

    def find(self, *keys, _gen=None):
        self.update()
        key = Key(*keys)
        current_obj = self
        current_pos = 0
        for kmap, tkey in key.unchain():
            if kmap is not None:
                if kmap != current_obj:
                    raise KeyError(
                        f"Tagged key {tkey} not from keymap {current_obj}"
                    )
            current_pos += current_obj._key2pos[tkey]
            current_obj = current_obj._key2reg[tkey]

        return current_pos, current_obj

    def whats_at(self, offset, _collect=None):
        if _collect is None:
            _collect = []
        if isinstance(self, Entry) or not self._key2reg:
            return self, _collect
        key = self._pos2key[offset]
        region, offset = self._pos2reg[offset]
        return region.whats_at(offset, _collect + [key])


